sys_ux_client_script.script:
/**

 * @param {params} params

 * @param {api} params.api

 * @param {TransformApiHelpers} params.helpers

 */

function evaluateProperty({ api, helpers }) {

    var data = api.data.top_product_from_top_publisher_1.output.top_products;

    var selectedPublishers = api.data.get_filter_publisher_1.output;

    var searchTerm = api.state.searchInput; // Example search term

    console.log("searchTerm", searchTerm);

    console.log("selectedPublisers", selectedPublishers);

    var selectedPublisherIds = selectedPublishers.flat().map(publisher => publisher.id);

    var selectedPublisherLabels = selectedPublishers.flat().map(publisher => publisher.label);



    // Get pagination details from the state

    var currentPage = api.state.currentPage || 1; // Default to page 1

    var recordsPerPage = api.state.recordsPerPage || 10; // Default to 8 records per page



    // Filter the data based on the search term

    var filteredData =data;
     filteredData = filteredData.filter(item => {

        // Assuming each item has a 'publisher' field which could be an 'id' or 'label'

        return selectedPublisherIds.includes(item.publisher) || selectedPublisherLabels.includes(item.publisher);

    });

    if (searchTerm && searchTerm.trim()) {

        filteredData = filteredData.filter(item => {

            return Object.values(item).some(value =>

                String(value).toLowerCase().includes(searchTerm.toLowerCase())

            );

        });

    }



    // Apply pagination

    var startIndex = (currentPage - 1) * recordsPerPage;

    var endIndex = startIndex + recordsPerPage;

    var paginatedData = filteredData.slice(startIndex, endIndex);



    // Return the paginated and filtered data

    return data;

    return {

        currentPage: currentPage,

        recordsPerPage: recordsPerPage,

        totalRecords: filteredData.length,

        totalPages: Math.ceil(filteredData.length / recordsPerPage),

        data: paginatedData

    };

}
